//! Keycode name tables, generated by `build.rs`:
//! - QMK names and labels from vial-qmk `data/constants/keycodes/*.hjson`;
//! - vial-gui protocol 6 names, used by `.vil` files (`KC_LSHIFT`, `FN_MO13`, `USER00`...).

use std::collections::HashMap;
use std::sync::OnceLock;

include!(concat!(env!("OUT_DIR"), "/keycodes_generated.rs"));

#[derive(Debug, Clone, Copy)]
pub struct QmkEntry {
    pub key: &'static str,
    pub label: &'static str,
    pub aliases: &'static [&'static str],
}

impl QmkEntry {
    /// Shortest name among the key and its aliases (e.g. `KC_ESC`).
    pub fn short_name(&self) -> &'static str {
        std::iter::once(self.key)
            .chain(self.aliases.iter().copied())
            .filter(|n| !n.starts_with('!'))
            .min_by_key(|n| n.len())
            .unwrap_or(self.key)
    }
}

pub fn qmk_by_code(code: u16) -> Option<QmkEntry> {
    let i = QMK_KEYCODES.binary_search_by_key(&code, |e| e.0).ok()?;
    let (_, key, label, aliases) = QMK_KEYCODES[i];
    Some(QmkEntry { key, label, aliases })
}

/// QMK code for a key name or alias (`KC_ESCAPE`, `KC_ESC`, `TL_LOWR`...).
pub fn qmk_code(name: &str) -> Option<u16> {
    static MAP: OnceLock<HashMap<&'static str, u16>> = OnceLock::new();
    let map = MAP.get_or_init(|| {
        let mut m = HashMap::new();
        for &(code, key, _, aliases) in QMK_KEYCODES {
            m.insert(key, code);
            for a in aliases.iter().filter(|a| !a.starts_with('!')) {
                m.entry(*a).or_insert(code);
            }
        }
        m
    });
    map.get(name).copied()
}

fn vial_map() -> &'static HashMap<&'static str, u16> {
    static MAP: OnceLock<HashMap<&'static str, u16>> = OnceLock::new();
    MAP.get_or_init(|| VIAL_NAMES.iter().copied().collect())
}

fn vial_const(name: &str) -> Option<u16> {
    vial_map().get(name).copied()
}

fn parse_number(s: &str) -> Option<u16> {
    let s = s.trim();
    match s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        Some(hex) => u16::from_str_radix(hex, 16).ok(),
        None => s.parse().ok(),
    }
}

/// Converts a keycode name as serialized by vial-gui (protocol 6) to its
/// numeric value. Mirrors vial-gui's `Keycode.deserialize`, including the
/// generated families (`MO(n)`, `USERnn`, `LTn(kc)`...) and masked forms
/// (`LCTL_T(KC_TAB)`, `C_S(KC_F5)`). Falls back to QMK names.
pub fn vial_code(name: &str) -> Option<u16> {
    let name = name.trim();
    if let Some(v) = vial_const(name) {
        return Some(v);
    }
    if name.starts_with("0x") || name.starts_with("0X") {
        return parse_number(name);
    }
    if let Some(n) = name.strip_prefix("USER") {
        let n: u16 = n.parse().ok()?;
        return (n < 64).then(|| vial_const("QK_KB").map(|b| b + n)).flatten();
    }
    if let Some(n) = name.strip_prefix('M').filter(|n| !n.is_empty() && n.bytes().all(|b| b.is_ascii_digit())) {
        let n: u16 = n.parse().ok()?;
        return (n < 256).then(|| vial_const("QK_MACRO").map(|b| b + n)).flatten();
    }
    if let (Some(open), true) = (name.find('('), name.ends_with(')')) {
        let outer = &name[..open];
        let inner = &name[open + 1..name.len() - 1];
        let layer_base = match outer {
            "MO" => Some("QK_MOMENTARY"),
            "DF" => Some("QK_DEF_LAYER"),
            "TG" => Some("QK_TOGGLE_LAYER"),
            "TT" => Some("QK_LAYER_TAP_TOGGLE"),
            "OSL" => Some("QK_ONE_SHOT_LAYER"),
            "TO" => Some("QK_TO"),
            "PDF" => Some("QK_PERSISTENT_DEF_LAYER"),
            _ => None,
        };
        if let Some(base) = layer_base {
            let n = parse_number(inner)?;
            return (n < 32).then(|| vial_const(base).map(|b| b + n)).flatten();
        }
        if outer == "TD" {
            let n = parse_number(inner)?;
            return (n < 256).then(|| vial_const("QK_TAP_DANCE").map(|b| b + n)).flatten();
        }
        let masked = if let Some(n) = outer.strip_prefix("LT").and_then(|n| n.parse::<u16>().ok()) {
            (n < 16).then(|| vial_const("QK_LAYER_TAP").map(|b| b | (n << 8))).flatten()
        } else {
            vial_const(&format!("{outer}(kc)"))
        };
        if let Some(outer_val) = masked {
            let inner_val = vial_code(inner)?;
            // only basic keycodes (possibly with mods) can be nested
            return (inner_val <= 0x1FFF && (outer_val & 0x00FF) == 0).then_some(outer_val | inner_val);
        }
    }
    qmk_code(name)
}

/// Parses a keycode written by a person (config file): everything
/// [`vial_code`] accepts, plus QMK's short modifier wrappers, nested
/// (`S(KC_F5)`, `C(KC_DOT)`, `C(S(KC_F5))`, `RALT(KC_E)`), `QK_KB_n` and
/// decimal/hex numbers.
pub fn parse_keycode(text: &str) -> Option<u16> {
    let t = text.trim();
    if let Some(v) = vial_code(t) {
        return Some(v);
    }
    if let Some(n) = t.strip_prefix("QK_KB_").and_then(|n| n.parse::<u16>().ok()) {
        return (n < 64).then_some(0x7E00 + n);
    }
    if !t.is_empty() && t.bytes().all(|b| b.is_ascii_digit()) {
        return t.parse().ok();
    }
    let open = t.find('(')?;
    if !t.ends_with(')') {
        return None;
    }
    let mods: u16 = match &t[..open] {
        "C" | "LCTL" => 0x01,
        "S" | "LSFT" => 0x02,
        "A" | "LALT" | "LOPT" => 0x04,
        "G" | "LGUI" | "LCMD" | "LWIN" => 0x08,
        "RCTL" => 0x11,
        "RSFT" => 0x12,
        "RALT" | "ROPT" | "ALGR" => 0x14,
        "RGUI" | "RCMD" | "RWIN" => 0x18,
        _ => return None,
    };
    let inner = parse_keycode(&t[open + 1..t.len() - 1])?;
    if inner > 0x1FFF {
        return None;
    }
    // nested wrappers combine their modifiers; the right-hand bit is shared
    Some((((inner >> 8) | mods) << 8) | (inner & 0xFF))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_tables_are_populated() {
        assert!(QMK_KEYCODES.len() > 500, "{}", QMK_KEYCODES.len());
        assert!(QMK_KEYCODES.windows(2).all(|w| w[0].0 < w[1].0), "sorted and unique");
        assert!(VIAL_NAMES.len() > 400);
    }

    #[test]
    fn qmk_lookups() {
        let esc = qmk_by_code(0x0029).unwrap();
        assert_eq!(esc.key, "KC_ESCAPE");
        assert_eq!(esc.short_name(), "KC_ESC");
        assert_eq!(qmk_code("KC_BSPC"), Some(0x2A));
        assert_eq!(qmk_code("QK_REP"), Some(0x7C79));
        assert_eq!(qmk_code("CW_TOGG"), Some(0x7C73));
    }

    #[test]
    fn vial_names_from_corne_vil() {
        let cases = [
            ("KC_ESCAPE", 0x0029),
            ("KC_LSHIFT", 0x00E1),
            ("KC_BSPACE", 0x002A),
            ("KC_SCOLON", 0x0033),
            ("FN_MO13", 0x7C77),
            ("FN_MO23", 0x7C78),
            ("QK_REPEAT_KEY", 0x7C79),
            ("QK_CAPS_WORD_TOGGLE", 0x7C73),
            ("QK_BOOT", 0x7C00),
            ("TG(4)", 0x5264),
            ("OSL(5)", 0x5285),
            ("LCTL_T(KC_TAB)", 0x212B),
            ("LCTL(KC_Z)", 0x011D),
            ("C_S(KC_F5)", 0x033E),
            ("LALT(KC_F12)", 0x0445),
            ("LSFT(KC_1)", 0x021E),
            ("USER00", 0x7E00),
            ("USER17", 0x7E11),
            ("LT2(KC_SPACE)", 0x422C),
            ("M3", 0x7703),
            ("TD(1)", 0x5701),
            ("0x7e12", 0x7E12),
            ("KC_ESC", 0x0029), // QMK alias fallback
        ];
        for (name, code) in cases {
            assert_eq!(vial_code(name), Some(code), "{name}");
        }
    }

    #[test]
    fn config_keycodes() {
        let cases = [
            ("KC_F10", 0x0043),
            ("S(KC_F5)", 0x023E),
            ("C(KC_DOT)", 0x0137),
            ("C(S(KC_F5))", 0x033E),
            ("A(KC_F12)", 0x0445),
            ("RALT(KC_E)", 0x1408),
            ("QK_KB_15", 0x7E0F),
            ("USER15", 0x7E0F),
            ("LCTL_T(KC_TAB)", 0x212B),
            ("TG(4)", 0x5264),
            ("0x7e12", 0x7E12),
            ("67", 67),
        ];
        for (name, code) in cases {
            assert_eq!(parse_keycode(name), Some(code), "{name}");
        }
        for bad in ["", "X(KC_A)", "C(MO(1))", "C(", "QK_KB_99", "KC_NOPE"] {
            assert_eq!(parse_keycode(bad), None, "{bad}");
        }
    }

    #[test]
    fn vial_names_reject_garbage() {
        for bad in ["", "NOPE", "MO(99)", "USER99", "LCTL_T(MO(1))", "TG(x)", "LCTL(", "M", "Mfoo", "0xZZ"] {
            assert_eq!(vial_code(bad), None, "{bad}");
        }
    }
}
